/**
 * Ghelsba Outpost walk graph, traced from the retail Vana'diel Atlas map (15x15 sheet, A-O / 1-15).
 * Grid units: gx 0..1 = column A, gy 0..1 = row 1, +gy is south. Everything sits in F-K / 5-11, so the
 * game's 12x12 ghelsba grid labels every point the same way.
 * Floor = areas (polygons with holes) + edges (polylines buffered by width/2) + node discs.
 * Cliff edges come from the Atlas outlines; walkable patches and heights were checked against
 * LandSandBoat regions.yaml (gx = (x + 640) / 80, gy = (800 - z) / 80).
 * Origin/cell match ghelsba.ts: OUT_X = -1520, OUT_Z = 150, CELL = 32 * 2.05 = 65.6.
 */
export const GHELSBA_X = -1520;
export const GHELSBA_Z = 150;
export const GHELSBA_CELL = 32 * 2.05;
export const GHELSBA_WIDTH = 0.14;
export type GhelsbaLevel = "low" | "mid" | "high" | "top" | "ramp" | "bridge";
export type GhelsbaNodeKind = "exit" | "door" | "junction" | "area" | "chamber" | "deadend";
export type GhelsbaNode = { id: string; gx: number; gy: number; grid: string; kind: GhelsbaNodeKind; r?: number; to?: string };
export type GhelsbaEdge = { id: string; from: string; to: string; level: GhelsbaLevel; width?: number; pts: [number, number][] };
export type GhelsbaArea = { id: string; kind: "floor"; grid: string; pts: [number, number][]; holes?: [number, number][][] };
/** Visual height bands (not needed for walking). height is yalms above the river floor. */
export type GhelsbaBand = { id: string; level: "low" | "mid" | "high" | "top"; height: number; grid: string; pts: [number, number][] };
export type GhelsbaPoi = { id: string; gx: number; gy: number; grid: string; label: string };
export type GhelsbaGraph = {
  nodes: GhelsbaNode[];
  edges: GhelsbaEdge[];
  areas: GhelsbaArea[];
  bands: GhelsbaBand[];
  /** Floor-height steps over 6 yalms inside the walkable floor. Optional thin colliders. */
  cliffs: [number, number][][];
  /** Atlas river centerlines (visual water; the river floor itself is walkable). */
  streams: [number, number][][];
  pois: GhelsbaPoi[];
};
