const W = (gx: number, gy: number) => ({ x: GHELSBA_X + gx * GHELSBA_CELL, z: GHELSBA_Z + gy * GHELSBA_CELL });
export const gridToWorld = W;
export const worldToGrid = (x: number, z: number) => ({ gx: (x - GHELSBA_X) / GHELSBA_CELL, gy: (z - GHELSBA_Z) / GHELSBA_CELL });
type V2 = { x: number; z: number };
type Seg = { ax: number; az: number; bx: number; bz: number; half: number; edge: string };
type Disc = { x: number; z: number; r: number; node: string };
type Ring = V2[];
export const GHELSBA_SEGS: Seg[] = [];
export const GHELSBA_DISCS: Disc[] = [];
/** World-space rings per area: [outer, ...holes]. */
export const GHELSBA_RINGS: { area: string; rings: Ring[] }[] = [];
for (const e of GHELSBA_GRAPH.edges) {
  const half = ((e.width ?? GHELSBA_WIDTH) * GHELSBA_CELL) / 2;
  for (let i = 0; i + 1 < e.pts.length; i++) {
    const a = W(e.pts[i][0], e.pts[i][1]);
    const b = W(e.pts[i + 1][0], e.pts[i + 1][1]);
    GHELSBA_SEGS.push({ ax: a.x, az: a.z, bx: b.x, bz: b.z, half, edge: e.id });
  }
}
for (const n of GHELSBA_GRAPH.nodes) {
  if (!n.r) continue;
  const c = W(n.gx, n.gy);
  GHELSBA_DISCS.push({ x: c.x, z: c.z, r: n.r * GHELSBA_CELL, node: n.id });
}
for (const a of GHELSBA_GRAPH.areas) {
  const rings: Ring[] = [a.pts.map(([gx, gy]) => W(gx, gy))];
  for (const h of a.holes ?? []) rings.push(h.map(([gx, gy]) => W(gx, gy)));
  GHELSBA_RINGS.push({ area: a.id, rings });
}
function nearOnSeg(px: number, pz: number, ax: number, az: number, bx: number, bz: number): V2 {
  const dx = bx - ax, dz = bz - az;
  const len2 = dx * dx + dz * dz;
  const t = len2 ? Math.max(0, Math.min(1, ((px - ax) * dx + (pz - az) * dz) / len2)) : 0;
  return { x: ax + t * dx, z: az + t * dz };
}
/** Even-odd test over the outer ring and its holes. */
function inRings(rings: Ring[], x: number, z: number): boolean {
  let inside = false;
  for (const ring of rings) {
    for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
      const a = ring[i], b = ring[j];
      if (a.z > z !== b.z > z && x < ((b.x - a.x) * (z - a.z)) / (b.z - a.z) + a.x) inside = !inside;
    }
  }
  return inside;
}
function ringNearest(rings: Ring[], x: number, z: number): { d: number; q: V2 } {
  let d = Infinity;
  let q: V2 = { x, z };
  for (const ring of rings) {
    for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
      const p = nearOnSeg(x, z, ring[j].x, ring[j].z, ring[i].x, ring[i].z);
      const dd = Math.hypot(x - p.x, z - p.z);
      if (dd < d) { d = dd; q = p; }
    }
  }
  return { d, q };
}
/** Signed room at a point: >= 0 is floor, the value is how far the nearest wall is. */
export function ghelsbaClearance(x: number, z: number): number {
  let best = -Infinity;
  for (const s of GHELSBA_SEGS) {
    const q = nearOnSeg(x, z, s.ax, s.az, s.bx, s.bz);
    best = Math.max(best, s.half - Math.hypot(x - q.x, z - q.z));
  }
  for (const d of GHELSBA_DISCS) best = Math.max(best, d.r - Math.hypot(x - d.x, z - d.z));
  for (const a of GHELSBA_RINGS) {
    const { d } = ringNearest(a.rings, x, z);
    best = Math.max(best, inRings(a.rings, x, z) ? d : -d);
  }
  return best;
}
/** Cheap floor test (no distance) for mask building at radius 0. */
function onFloor(x: number, z: number): boolean {
  for (const a of GHELSBA_RINGS) if (inRings(a.rings, x, z)) return true;
  for (const s of GHELSBA_SEGS) {
    const q = nearOnSeg(x, z, s.ax, s.az, s.bx, s.bz);
    if (Math.hypot(x - q.x, z - q.z) <= s.half) return true;
  }
  for (const d of GHELSBA_DISCS) if (Math.hypot(x - d.x, z - d.z) <= d.r) return true;
  return false;
}
export function inGhelsbaGraph(x: number, z: number, radius = 0): boolean {
  if (radius <= 0) return onFloor(x, z);
  return ghelsbaClearance(x, z) >= radius;
}
/** Nearest point with at least `radius` of room. Falls back to the nearest floor point on spots thinner than 2*radius. */
export function clampGhelsbaGraph(x: number, z: number, radius = 0): V2 {
  if (inGhelsbaGraph(x, z, radius)) return { x, z };
  const cands: V2[] = [];
  for (const s of GHELSBA_SEGS) {
    const q = nearOnSeg(x, z, s.ax, s.az, s.bx, s.bz);
    const dx = x - q.x, dz = z - q.z, len = Math.hypot(dx, dz) || 1;
    const keep = Math.max(0, s.half - radius);
    cands.push({ x: q.x + (dx / len) * keep, z: q.z + (dz / len) * keep });
  }
  for (const d of GHELSBA_DISCS) {
    const dx = x - d.x, dz = z - d.z, len = Math.hypot(dx, dz) || 1;
    const keep = Math.max(0, d.r - radius);
    cands.push({ x: d.x + (dx / len) * keep, z: d.z + (dz / len) * keep });
  }
  for (const a of GHELSBA_RINGS) {
    const { q } = ringNearest(a.rings, x, z);
    const dx = q.x - x, dz = q.z - z, len = Math.hypot(dx, dz) || 1;
    for (const k of [1, -1]) cands.push({ x: q.x + k * (dx / len) * (radius + 0.05), z: q.z + k * (dz / len) * (radius + 0.05) });
  }
  cands.sort((p, q) => Math.hypot(p.x - x, p.z - z) - Math.hypot(q.x - x, q.z - z));
  let fallback: V2 | null = null;
  for (const c of cands.slice(0, 6)) {
    let p = c;
    let room = ghelsbaClearance(p.x, p.z);
    // climb the clearance field a little when a candidate sits on a thin or concave spot
    for (let it = 0; it < 24 && room < radius; it++) {
      const h = 0.5;
      const gx = ghelsbaClearance(p.x + h, p.z) - ghelsbaClearance(p.x - h, p.z);
      const gz = ghelsbaClearance(p.x, p.z + h) - ghelsbaClearance(p.x, p.z - h);
      const g = Math.hypot(gx, gz);
      if (g < 1e-9) break;
      const step = Math.max(0.25, radius - room);
      p = { x: p.x + (gx / g) * step, z: p.z + (gz / g) * step };
      room = ghelsbaClearance(p.x, p.z);
    }
    if (room >= radius - 1e-6) return p;
    if (!fallback && room >= 0) fallback = p;
  }
  return fallback ?? cands[0] ?? { x, z };
}
/** 1 = floor. n = 12 * res covers the game's 12x12 ghelsba grid (A-L / 1-12). */
export function buildGhelsbaMask(res = 16): { res: number; n: number; data: Uint8Array } {
  const n = 12 * res;
  const data = new Uint8Array(n * n);
  for (let j = 0; j < n; j++)
    for (let i = 0; i < n; i++) {
      const p = W((i + 0.5) / res, (j + 0.5) / res);
      if (onFloor(p.x, p.z)) data[j * n + i] = 1;
    }
  return { res, n, data };
}
type Rect = { minX: number; maxX: number; minZ: number; maxZ: number };
/** Row strips of the mask, for the minimap or rect-based code (same shape as passMaskRects). */
export function ghelsbaMaskRects(res = 16): Rect[] {
  const m = buildGhelsbaMask(res);
  const cell = GHELSBA_CELL / res;
  const out: Rect[] = [];
  for (let j = 0; j < m.n; j++) {
    let i = 0;
    while (i < m.n) {
      if (!m.data[j * m.n + i]) { i++; continue; }
      const s = i;
      while (i < m.n && m.data[j * m.n + i]) i++;
      out.push({ minX: GHELSBA_X + s * cell, maxX: GHELSBA_X + i * cell, minZ: GHELSBA_Z + j * cell, maxZ: GHELSBA_Z + (j + 1) * cell });
    }
  }
  return out;
}
/** Retail square of a grid point (A-L / 1-12 like ZONE_GRIDS "ghelsba"). */
export function ghelsbaGridSquare(gx: number, gy: number): string {
  const col = Math.floor(gx), row = Math.floor(gy);
  if (col < 0 || row < 0 || col >= 12 || row >= 12) return "?";
  return `${"ABCDEFGHIJKL"[col]}-${row + 1}`;
}

